(function () {
  var DEFAULT_LIVE_API_BASE_URL = "https://esthtics-backend.onrender.com";

  function resolveApiBaseUrl() {
    var qsApi = "";
    var winApi = "";
    var storedApi = "";
    var host = "";

    try {
      qsApi = (
        new URLSearchParams(window.location.search).get("apiBase") || ""
      ).trim();
    } catch (e) {}
    try {
      winApi = String(window.__ESTI_API_BASE_URL__ || "").trim();
    } catch (e) {}
    try {
      storedApi = String(
        window.localStorage.getItem("ESTI_API_BASE_URL") || "",
      ).trim();
    } catch (e) {}
    try {
      host = String(window.location.hostname || "")
        .trim()
        .toLowerCase();
    } catch (e) {}

    if (qsApi) {
      try {
        window.localStorage.setItem("ESTI_API_BASE_URL", qsApi);
      } catch (e) {}
    }

    // Prefer local API on localhost; otherwise fall back to live API.
    var localFallback =
      host === "localhost" || host === "127.0.0.1"
        ? "http://localhost:4001"
        : "";
    var resolved =
      qsApi ||
      winApi ||
      storedApi ||
      localFallback ||
      DEFAULT_LIVE_API_BASE_URL;
    return resolved ? resolved.replace(/\/$/, "") : "";
  }

  var CONFIG = {
    API_BASE_URL: resolveApiBaseUrl(),
    APPS_SCRIPT_URL: "PASTE_YOUR_APPS_SCRIPT_WEB_APP_URL_HERE",
    PUBLIC_QUIZ_URL: "https://tec-daily-three.netlify.app",
    JOIN_URL: "https://www.esticonfidential.com",
    DEEP_DIVE_URL: "https://www.esticonfidential.com",
  };

  // ---------- LOGO ----------
  var LOGO_B64 =
    "";

  // ---------- CONTENT: today's three + optional bonus ----------

  // ---------- TODAY'S DATA ----------
  // All of this arrives from GET /api/quiz/today. Nothing is hard-coded any
  // more; an empty day simply renders the "nothing scheduled" screen.
  var QUEUE = []; // the daily three, in slot order
  var BONUS = null; // optional fourth question, or null
  var FEATURED = null; // Q6 promo screen, only on days the admin set one
  var RESULTS = null; // filled from GET /api/quiz/results at the end
  var TODAY = { questionCount: 0, hasBonus: false, themes: [] };
  var PROGRESS = {
    answeredCount: 0,
    requiredCount: 0,
    correctCount: 0,
    completed: false,
    bonusPlayed: false,
    nextSlot: null,
  };
  var JOIN_URL = "";

  // ---------- STATE ----------
  var el = document.getElementById("ed-app");
  var me = getIdentity();
  var state = { i: 0, results: [], streak: readStreak(), playingBonus: false };

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (ch) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
      }[ch];
    });
  }

  // Identity order: URL params (iframe from Circle) → window.circleUser (same page) → demo.
  function getIdentity() {
    try {
      var p = new URLSearchParams(window.location.search);
      var urlUid = p.get("uid") || p.get("publicUid") || p.get("public_uid");
      var urlEmail = p.get("email") || "";
      var urlName = p.get("name") || "";
      if (urlUid || urlEmail) {
        return {
          uid: urlUid || urlEmail,
          name: urlName.split(" ")[0],
          fullName: urlName,
          email: urlEmail,
          demo: false,
          source: "url",
        };
      }
    } catch (e) {}

    try {
      var u = window.circleUser;
      if (u) {
        var uid = u.publicUid || u.public_uid || u.email;
        if (uid) {
          var full =
            u.name || [u.firstName, u.lastName].filter(Boolean).join(" ");
          return {
            uid: uid,
            name: u.firstName || full.split(" ")[0],
            fullName: full,
            email: u.email || "",
            demo: false,
            source: "circleUser",
          };
        }
      }
    } catch (e) {}

    // No member details at all — local testing. Plays as the "test-user"
    // member, whose name lives in the database. The name stays empty here so a
    // placeholder is never sent to be saved; firstName() shows one.
    return {
      uid: "test-user",
      name: "",
      fullName: "",
      email: "",
      demo: true,
      source: "demo",
    };
  }

  function readStreak() {
    try {
      return 0; // real value arrives with GET /api/quiz/today
    } catch (e) {
      return 0;
    }
  }

  function goTo(url, fallbackMsg) {
    if (!url || url.indexOf("PASTE_") === 0) {
      alert(fallbackMsg || "Link not set yet.");
      return;
    }
    try {
      if (window.navigateToUrl) {
        window.navigateToUrl(url);
        return;
      }
    } catch (e) {}
    window.open(url, "_blank");
  }

  function apiOn() {
    return !!(CONFIG.API_BASE_URL && CONFIG.API_BASE_URL.indexOf("http") === 0);
  }

  function apiUrl(path) {
    return CONFIG.API_BASE_URL.replace(/\/$/, "") + path;
  }

  function fetchJson(url, opts) {
    return fetch(url, opts).then(function (r) {
      return r.json().then(function (data) {
        if (!r.ok)
          throw new Error(data.error || "Request failed (" + r.status + ")");
        return data;
      });
    });
  }

  function identityQuery() {
    return new URLSearchParams({
      uid: me.uid,
      email: me.email || "",
      name: me.fullName || me.name || "",
    }).toString();
  }

  function fetchToday() {
    return fetchJson(apiUrl("/api/quiz/today?" + identityQuery()));
  }

  function fetchResults() {
    return fetchJson(
      apiUrl("/api/quiz/results?uid=" + encodeURIComponent(me.uid)),
    );
  }

  function fetchHistory() {
    return fetchJson(
      apiUrl("/api/quiz/answers?uid=" + encodeURIComponent(me.uid)),
    );
  }

  function saveAnswer(questionId, selectedIndex) {
    return fetchJson(apiUrl("/api/quiz/answer"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        uid: me.uid,
        email: me.email || "",
        name: me.fullName || me.name || "",
        questionId: questionId,
        selectedIndex: selectedIndex,
      }),
    });
  }

  // The API speaks in its own field names. The screens below were built around
  // the original card shape, so everything is mapped once, here.
  function toCard(q) {
    return {
      id: q.id,
      slug: q.id,
      slot: q.slot,
      isBonus: !!q.isBonus,
      theme: q.theme ? q.theme.key : "",
      themeLabel: q.theme ? q.theme.label : "",
      track: q.displayTag || "",
      q: q.q,
      opts: q.opts || [],
      alreadyAnswered: !!q.alreadyAnswered,
      answeredIndex:
        typeof q.selectedIndex === "number" ? q.selectedIndex : null,
      answeredCorrect: q.correct,
      correct: null,
      aha: "",
      lbl: "",
      chair: "",
      goDeeperUrl: "",
      deepdive: { text: "", sourceLabel: "", sourceUrl: "" },
    };
  }

  function applyTodayPayload(data) {
    QUEUE = (data.questions || []).map(toCard);
    BONUS = data.bonus ? toCard(data.bonus) : null;
    FEATURED = data.featured || null;
    TODAY = data.today || TODAY;
    PROGRESS = data.progress || PROGRESS;
    JOIN_URL = data.joinUrl || "";

    if (data.member) {
      if (data.member.name) me.name = data.member.name;
      if (typeof data.member.currentStreak === "number")
        state.streak = data.member.currentStreak;
    }

    // Rebuild what she already answered today, so a resumed session still
    // scores correctly on the results screen.
    state.results = QUEUE.filter(function (c) {
      return c.alreadyAnswered;
    }).map(function (c) {
      return {
        slug: c.slug,
        correct: !!c.answeredCorrect,
        theme: c.theme,
        themeLabel: c.themeLabel,
      };
    });
  }

  // Shown when there are no member details, e.g. testing locally. Display only —
  // never sent to the API, so it can't end up saved as a member's name.
  var TEST_NAME = "Test User";

  function firstName() {
    // The test member's stored name is this same placeholder; show it whole
    // rather than cutting it down to "Test".
    if (me.name === TEST_NAME) return TEST_NAME;
    return String(me.name || "").split(" ")[0] || TEST_NAME;
  }

  function greeting() {
    var h = new Date().getHours();
    if (h < 12) return "Good morning";
    if (h < 18) return "Good afternoon";
    return "Good evening";
  }

  function longDate() {
    try {
      return new Date().toLocaleDateString(undefined, {
        weekday: "long",
        day: "numeric",
        month: "long",
      });
    } catch (e) {
      return "Today";
    }
  }

  function firstUnansweredIndex() {
    for (var i = 0; i < QUEUE.length; i++) {
      if (!QUEUE[i].alreadyAnswered) return i;
    }
    return QUEUE.length;
  }

  // ---------- CHROME (shared header) ----------
  function chrome(streak, progress) {
    var logoHtml = LOGO_B64
      ? '<img class="logo" src="data:image/png;base64,' +
        LOGO_B64 +
        '" alt="TEC">'
      : "";
    return (
      "" +
      '<div class="top">' +
      '<div class="brandwrap">' +
      logoHtml +
      '<span class="bname">The Esti Confidential</span></div>' +
      '<div class="streak">🔥 ' +
      streak +
      "-day streak</div>" +
      "</div>" +
      '<div class="bar"><i style="width:' +
      (progress || 0) +
      '%"></i></div>'
    );
  }

  // ---------- HOME (Q2) ----------
  function renderHome() {
    var chips = (TODAY.themes || [])
      .map(function (t) {
        return '<span class="tag">' + esc(t) + "</span>";
      })
      .join(" ");

    el.innerHTML =
      chrome(state.streak, 0) +
      '<div class="screen">' +
      '<div class="kick">' +
      esc(longDate()) +
      "</div>" +
      "<h1>" +
      esc(greeting()) +
      ", " +
      esc(firstName()) +
      "</h1>" +
      '<div class="msgcard"><div class="lbl">Today</div>' +
      TODAY.questionCount +
      " question" +
      (TODAY.questionCount === 1 ? "" : "s") +
      (TODAY.hasBonus ? ", plus a bonus question if you want it." : ".") +
      "</div>" +
      (chips
        ? '<div class="otherwrap"><div class="h">Today’s themes</div>' +
          chips +
          "</div>"
        : "") +
      '<button class="btn" id="ed-play">Start today’s quiz</button>' +
      '<div class="acedLine">Answer all ' +
      TODAY.questionCount +
      " to keep your streak.</div>" +
      "</div>";

    document.getElementById("ed-play").onclick = startQuiz;
  }

  // ---------- RESUME (Q9) ----------
  function renderResume() {
    var rows = QUEUE.map(function (c, i) {
      var done = c.alreadyAnswered;
      return (
        '<div class="otherrow"><span>' +
        (i + 1) +
        " · " +
        esc(c.themeLabel) +
        '</span><span class="pct">' +
        (done ? "answered" : "not yet") +
        "</span></div>"
      );
    }).join("");

    var next = firstUnansweredIndex();

    el.innerHTML =
      chrome(
        state.streak,
        Math.round((PROGRESS.answeredCount / Math.max(1, QUEUE.length)) * 100),
      ) +
      '<div class="screen">' +
      '<div class="kick">' +
      esc(longDate()) +
      "</div>" +
      "<h1>Welcome back, " +
      esc(firstName()) +
      "</h1>" +
      '<div class="sub">You started today’s quiz earlier.</div>' +
      '<div class="msgcard"><div class="lbl">Where you got to</div>' +
      PROGRESS.answeredCount +
      " of " +
      QUEUE.length +
      " answered</div>" +
      '<div class="otherwrap">' +
      rows +
      "</div>" +
      '<button class="btn" id="ed-resume">Continue from question ' +
      (next + 1) +
      "</button>" +
      '<div class="acedLine">Your earlier answers are saved.</div>' +
      "</div>";

    document.getElementById("ed-resume").onclick = startQuiz;
  }

  // ---------- ALREADY PLAYED (Q10) ----------
  function renderAlreadyPlayed() {
    var score = state.results.filter(function (r) {
      return r.correct;
    }).length;

    el.innerHTML =
      chrome(state.streak, 100) +
      '<div class="screen">' +
      '<div class="kick">' +
      esc(longDate()) +
      "</div>" +
      "<h1>You are done for today</h1>" +
      '<div class="sub">You completed today’s quiz already.</div>' +
      '<div class="score">' +
      score +
      "<small> / " +
      state.results.length +
      "</small></div>" +
      '<div class="streakbig"><div class="n">🔥 ' +
      state.streak +
      '</div><div class="c">day streak</div></div>' +
      '<div class="msgcard"><div class="lbl">Next quiz</div>Tomorrow morning. Come back to keep your streak going.</div>' +
      '<button class="btn" id="ed-see">View today’s results</button>' +
      "</div>";

    document.getElementById("ed-see").onclick = function () {
      renderEnd();
    };
  }

  // ---------- NOTHING SCHEDULED ----------
  function renderEmptyDay() {
    el.innerHTML =
      chrome(state.streak, 0) +
      '<div class="screen">' +
      '<div class="kick">' +
      esc(longDate()) +
      "</div>" +
      "<h1>No quiz today</h1>" +
      '<div class="sub">Nothing has been scheduled for today. Check back tomorrow.</div>' +
      "</div>";
  }

  function startQuiz() {
    state.i = firstUnansweredIndex();
    state.playingBonus = false;
    renderQ();
  }

  function currentCard() {
    return state.playingBonus ? BONUS : QUEUE[state.i];
  }

  // ---------- QUESTION (Q3) ----------
  function renderQ() {
    var c = currentCard();
    if (!c) {
      afterDailyQuestions();
      return;
    }

    var answeredSoFar = state.playingBonus ? QUEUE.length : state.i;
    var progress = Math.round(
      (answeredSoFar / Math.max(1, QUEUE.length)) * 100,
    );
    var tagText = c.track ? c.track : c.themeLabel;

    el.innerHTML =
      chrome(state.streak, progress) +
      '<div class="screen">' +
      (c.isBonus
        ? '<div class="kick">Bonus round</div>'
        : '<div class="kick">Question ' +
          (state.i + 1) +
          " of " +
          QUEUE.length +
          "</div>") +
      '<div class="tag">' +
      esc(tagText) +
      "</div>" +
      '<div class="q">' +
      esc(c.q) +
      "</div>" +
      '<div class="opts" id="ed-opts">' +
      c.opts
        .map(function (o, idx) {
          return (
            '<button class="opt" data-i="' + idx + '">' + esc(o) + "</button>"
          );
        })
        .join("") +
      "</div>" +
      '<div id="ed-reveal"></div>' +
      "</div>";

    Array.prototype.forEach.call(
      document.querySelectorAll("#ed-opts .opt"),
      function (btn) {
        btn.onclick = function () {
          choose(parseInt(btn.getAttribute("data-i"), 10));
        };
      },
    );
  }

  // Saving an answer waits on the server, which can take a couple of seconds.
  // Meanwhile the tapped option holds a gold "checking" state with a spinner,
  // the others step back, and nothing can be tapped twice.
  function setAnswerPending(idx, pending) {
    var opts = document.getElementById("ed-opts");
    if (!opts) return;
    opts.classList.toggle("saving", pending);
    opts.setAttribute("aria-busy", pending ? "true" : "false");
    Array.prototype.forEach.call(
      opts.querySelectorAll(".opt"),
      function (btn, i) {
        btn.disabled = pending;
        btn.classList.toggle("picked", pending && i === idx);
      },
    );
    // Clears an earlier "could not save" message when she tries again.
    var box = document.getElementById("ed-reveal");
    if (box) box.innerHTML = "";
  }

  // Each answer is submitted the moment it is tapped (Q4/Q5).
  function choose(idx) {
    var c = currentCard();
    setAnswerPending(idx, true);

    saveAnswer(c.id, idx)
      .then(function (res) {
        setAnswerPending(idx, false);
        revealAnswer(c, idx, res);
      })
      .catch(function (err) {
        setAnswerPending(idx, false);
        renderInlineError(err.message || String(err));
      });
  }

  function renderInlineError(message) {
    var box = document.getElementById("ed-reveal");
    if (!box) return;
    box.innerHTML =
      '<div class="reveal"><div class="aha">Could not save that answer. ' +
      esc(message) +
      "</div></div>";
  }

  function revealAnswer(c, idx, payload) {
    var correctIndex = payload.correctIndex;
    var correct = !!payload.correct;

    c.correct = correctIndex;
    c.alreadyAnswered = true;
    c.answeredIndex = idx;
    c.answeredCorrect = correct;
    c.aha = payload.whyThisMatters || "";
    c.lbl = payload.chairLabel || "";
    c.chair = payload.chairText || "";
    c.goDeeperUrl = payload.goDeeperUrl || "";
    c.deepdive = payload.deepDive || {
      text: "",
      sourceLabel: "",
      sourceUrl: "",
    };

    // The bonus never counts towards the score or the streak.
    if (!c.isBonus) {
      state.results.push({
        slug: c.slug,
        correct: correct,
        theme: c.theme,
        themeLabel: c.themeLabel,
      });
    }
    if (payload.progress) PROGRESS = payload.progress;
    if (payload.streak && typeof payload.streak.current === "number") {
      state.streak = payload.streak.current;
    }

    Array.prototype.forEach.call(
      document.querySelectorAll("#ed-opts .opt"),
      function (btn, i) {
        btn.disabled = true;
        if (i === correctIndex) btn.classList.add("correct");
        else if (i === idx) btn.classList.add("wrong");
        else btn.classList.add("dim");
      },
    );

    if (correct) {
      fireConfetti();
      fireVibration();
    }

    var isLast = state.playingBonus || state.i === QUEUE.length - 1;

    document.getElementById("ed-reveal").innerHTML =
      '<div class="reveal">' +
      '<div class="kick">' +
      (correct ? "Correct" : "Not quite") +
      "</div>" +
      (c.aha ? '<div class="aha">' + esc(c.aha) + "</div>" : "") +
      (c.chair
        ? '<div class="chair"><div class="lbl">' +
          esc(c.lbl || "Say this to a client") +
          '</div><div class="txt">' +
          esc(c.chair) +
          "</div></div>"
        : "") +
      revealButtonsHtml(c) +
      '<button class="btn" id="ed-next">' +
      (isLast ? "See results" : "Next question") +
      "</button>" +
      "</div>";

    wireRevealButtons(c);
    document.getElementById("ed-next").onclick = goNext;
  }

  function revealButtonsHtml(c) {
    // Go deeper only appears when that question actually has something behind it.
    if (c.deepdive && c.deepdive.text) {
      return '<div class="row"><button class="mini deep" id="ed-go-deeper">Go deeper</button></div>';
    }
    if (c.goDeeperUrl) {
      return '<div class="row"><button class="mini deep" id="ed-go-deeper-link">Go deeper</button></div>';
    }
    return "";
  }

  function wireRevealButtons(c) {
    var deepBtn = document.getElementById("ed-go-deeper");
    if (deepBtn) {
      deepBtn.onclick = function () {
        renderDeepDive(c);
      };
    }
    var linkBtn = document.getElementById("ed-go-deeper-link");
    if (linkBtn) {
      linkBtn.onclick = function () {
        goTo(c.goDeeperUrl, "Link not set yet.");
      };
    }
  }

  function goNext() {
    if (state.playingBonus) {
      afterBonus();
      return;
    }
    if (state.i < QUEUE.length - 1) {
      state.i += 1;
      renderQ();
      return;
    }
    afterDailyQuestions();
  }

  function afterDailyQuestions() {
    if (BONUS && !BONUS.alreadyAnswered) {
      renderBonusOffer();
      return;
    }
    afterBonus();
  }

  function afterBonus() {
    if (FEATURED) {
      renderFeatured();
      return;
    }
    renderEnd();
  }

  // ---------- BONUS OFFER (Q7) ----------
  function renderBonusOffer() {
    el.innerHTML =
      chrome(state.streak, 100) +
      '<div class="screen">' +
      '<div class="kick">Bonus available</div>' +
      '<div class="score">+1</div>' +
      '<div class="sub">Bonus question today</div>' +
      '<div class="msgcard"><div class="lbl">' +
      esc(BONUS.themeLabel) +
      "</div>One extra question, just for fun.</div>" +
      '<div class="acedLine">Optional. It does not count towards your score, and skipping it will not affect your streak.</div>' +
      '<button class="btn" id="ed-bonus-play">Play the bonus</button>' +
      '<button class="ghost" id="ed-bonus-skip">Skip to my results</button>' +
      "</div>";

    document.getElementById("ed-bonus-play").onclick = function () {
      state.playingBonus = true;
      renderQ();
    };
    document.getElementById("ed-bonus-skip").onclick = afterBonus;
  }

  // ---------- FEATURED CONTENT (Q6) ----------
  function renderFeatured() {
    el.innerHTML =
      chrome(state.streak, 100) +
      '<div class="screen">' +
      '<div class="kick">Featured</div>' +
      (FEATURED.imageUrl
        ? '<img class="feat-img" id="ed-featured-img" alt="" src="' +
          esc(FEATURED.imageUrl) +
          '">'
        : "") +
      "<h1>" +
      esc(FEATURED.title) +
      "</h1>" +
      (FEATURED.bodyText
        ? '<div class="sub">' + esc(FEATURED.bodyText) + "</div>"
        : "") +
      (FEATURED.linkUrl
        ? '<button class="btn" id="ed-featured-cta">' +
          esc(FEATURED.buttonLabel || "Find out more") +
          "</button>"
        : "") +
      '<button class="ghost" id="ed-featured-skip">Skip</button>' +
      '<div class="acedLine">This screen does not affect your score or your streak.</div>' +
      "</div>";

    // A broken or mistyped image link shouldn't leave an empty box on screen.
    var img = document.getElementById("ed-featured-img");
    if (img) {
      img.onerror = function () {
        img.remove();
      };
    }

    var cta = document.getElementById("ed-featured-cta");
    if (cta) {
      cta.onclick = function () {
        goTo(FEATURED.linkUrl, "Link not set yet.");
      };
    }
    document.getElementById("ed-featured-skip").onclick = renderEnd;
  }

  function renderDeepDive(c) {
    var progress = Math.round((state.i / QUEUE.length) * 100);
    var sourceHtml = c.deepdive.sourceUrl
      ? '<div class="row"><button class="mini" id="ed-source">' +
        (c.deepdive.sourceLabel || "Source") +
        "</button></div>"
      : "";
    // The deep dive leads on to the question's Go deeper link (or the default
    // one from Settings), which the reveal screen can't show alongside it.
    var linkHtml = c.goDeeperUrl
      ? '<div class="row"><button class="mini deep" id="ed-go-deeper-link">Go deeper</button></div>'
      : "";
    el.innerHTML =
      chrome(state.streak, progress) +
      '<div class="screen">' +
      '<div class="kick">Go deeper</div>' +
      '<div class="tag">' +
      c.themeLabel +
      "</div>" +
      '<div class="aha">' +
      c.deepdive.text +
      "</div>" +
      sourceHtml +
      linkHtml +
      '<button class="btn" id="ed-next">' +
      (state.i === QUEUE.length - 1 ? "See results" : "Next question") +
      "</button>" +
      "</div>";
    wireRevealButtons(c);
    var srcBtn = document.getElementById("ed-source");
    if (srcBtn)
      srcBtn.onclick = function () {
        goTo(c.deepdive.sourceUrl, "Link not set yet.");
      };
    document.getElementById("ed-next").onclick = goNext;
  }

  // ---------- CONFETTI + VIBRATION ----------
  function fireConfetti() {
    var wrap = document.createElement("div");
    wrap.className = "confetti-wrap";
    document.body.appendChild(wrap);
    var colors = ["#E0AC69", "#8C5B3A", "#196B24", "#E97132"];
    for (var n = 0; n < 40; n++) {
      var p = document.createElement("div");
      var x = Math.random() * 100;
      var size = 6 + Math.random() * 6;
      p.style.cssText =
        "position:absolute;top:-10px;left:" +
        x +
        "vw;width:" +
        size +
        "px;height:" +
        size * 0.4 +
        "px;" +
        "background:" +
        colors[n % colors.length] +
        ";opacity:.9;transform:rotate(" +
        Math.random() * 360 +
        "deg);" +
        "animation:edfall " +
        (1.2 + Math.random() * 1.2) +
        "s ease-in forwards;animation-delay:" +
        Math.random() * 0.2 +
        "s";
      wrap.appendChild(p);
    }
    if (!document.getElementById("ed-confetti-kf")) {
      var st = document.createElement("style");
      st.id = "ed-confetti-kf";
      st.textContent =
        "@keyframes edfall{to{transform:translateY(100vh) rotate(360deg);opacity:0}}";
      document.head.appendChild(st);
    }
    setTimeout(function () {
      wrap.remove();
    }, 2600);
  }

  function fireVibration() {
    try {
      if (navigator.vibrate) navigator.vibrate([40, 30, 40]);
    } catch (e) {}
  }

  // ---------- END SCREEN ----------
  function communityRows(byTheme) {
    if (!byTheme || !byTheme.length) return "";
    return byTheme
      .map(function (t) {
        return (
          '<div class="otherrow"><span>' +
          esc(t.label) +
          '</span><span class="pct">You ' +
          t.you +
          "% · Community " +
          t.community +
          "%</span></div>"
        );
      })
      .join("");
  }

  function dotsHtml(results) {
    return (
      '<div class="dots">' +
      results
        .map(function (r) {
          return (
            '<div class="dot ' + (r.correct ? "correct" : "wrong") + '"></div>'
          );
        })
        .join("") +
      "</div>"
    );
  }

  // The community comparison is a second request: fetched once, shown as a
  // shimmer while it is on its way, and left out quietly if it can't be loaded.
  var RESULTS_UNAVAILABLE = false;
  var resultsInFlight = false;

  function communityHtml() {
    if (!RESULTS) {
      if (RESULTS_UNAVAILABLE) return "";
      return (
        '<div id="ed-community-loading" aria-busy="true">' +
        '<div class="otherwrap"><div class="skel skel-h"></div>' +
        '<div class="skel skel-row"></div><div class="skel skel-row"></div></div>' +
        '<div class="skel skel-card"></div>' +
        "</div>"
      );
    }
    var community = RESULTS.community || null;
    var byTheme = RESULTS.byTheme || [];
    return (
      (byTheme.length
        ? '<div class="otherwrap"><div class="h">You vs the community</div>' +
          communityRows(byTheme) +
          "</div>"
        : "") +
      (community
        ? '<div class="msgcard"><div class="lbl">Today across the community</div>' +
          community.aced +
          " of " +
          community.played +
          " estis aced it.</div>"
        : "")
    );
  }

  function renderEnd(refresh) {
    // Also wired straight to onclick, which passes an event — only an explicit
    // true means "the community numbers just landed".
    var refreshing = refresh === true;
    var score = state.results.filter(function (r) {
      return r.correct;
    }).length;
    var max = state.results.length;

    el.innerHTML =
      chrome(state.streak, 100) +
      // A refresh only fills in the community section, so the screen itself
      // doesn't replay its entrance; just the new part fades in.
      '<div class="screen' +
      (refreshing ? " still" : "") +
      '">' +
      '<div class="kick">Today’s results</div>' +
      '<div class="score">' +
      score +
      "<small> / " +
      max +
      "</small></div>" +
      '<div class="sub">' +
      esc(longDate()) +
      "</div>" +
      '<div class="streakbig"><div class="n">🔥 ' +
      state.streak +
      '</div><div class="c">day streak</div></div>' +
      '<div class="cardshare">' +
      '<div class="t">The Esti Confidential Challenge</div>' +
      dotsHtml(state.results) +
      "</div>" +
      "<div" +
      (refreshing ? ' class="arrive"' : "") +
      ">" +
      communityHtml() +
      "</div>" +
      '<button class="ghost" id="ed-stats">My total stats</button>' +
      (JOIN_URL
        ? '<div class="join"><div class="h">Know an esti who’d love this?</div>' +
          '<div class="p">Share The Esti Confidential with a friend.</div>' +
          '<button class="btn" id="ed-refer">Tell a friend</button></div>'
        : "") +
      "</div>";

    document.getElementById("ed-stats").onclick = renderStats;

    var refer = document.getElementById("ed-refer");
    if (refer) {
      refer.onclick = function () {
        goTo(JOIN_URL, "Link not set yet.");
      };
    }

    if (!RESULTS && !RESULTS_UNAVAILABLE && !resultsInFlight) {
      resultsInFlight = true;
      fetchResults()
        .then(function (data) {
          if (data && data.results) {
            RESULTS = data.results;
            if (typeof RESULTS.streak === "number")
              state.streak = RESULTS.streak;
          } else {
            RESULTS_UNAVAILABLE = true;
          }
        })
        .catch(function () {
          // The score still stands without the comparison.
          RESULTS_UNAVAILABLE = true;
        })
        .then(function () {
          resultsInFlight = false;
          // Only repaint if she is still on this screen — never pull her back
          // from the stats page.
          if (document.getElementById("ed-community-loading")) renderEnd(true);
        });
    }
  }

  // ---------- STATS SCREEN ----------
  function renderStats() {
    el.innerHTML =
      chrome(state.streak, 100) +
      '<div class="screen"><div class="kick">My total stats</div><h1>Loading…</h1>' +
      waitingHtml("Adding up your answers") +
      "</div>";

    fetchHistory()
      .then(function (data) {
        var answers = (data.answers || []).filter(function (a) {
          return !a.isBonus;
        });

        var byTheme = {};
        answers.forEach(function (a) {
          var label = a.theme ? a.theme.label : "Other";
          if (!byTheme[label]) byTheme[label] = { correct: 0, answered: 0 };
          byTheme[label].answered += 1;
          if (a.correct) byTheme[label].correct += 1;
        });

        var rows = Object.keys(byTheme)
          .map(function (label) {
            var d = byTheme[label];
            var pct = d.answered
              ? Math.round((d.correct / d.answered) * 100)
              : 0;
            return (
              '<div class="otherrow"><span>' +
              esc(label) +
              '</span><span class="pct">' +
              pct +
              "% · " +
              d.correct +
              "/" +
              d.answered +
              "</span></div>"
            );
          })
          .join("");

        var member = data.member || {};

        el.innerHTML =
          chrome(state.streak, 100) +
          '<div class="screen">' +
          '<div class="kick">My total stats</div>' +
          '<div class="streakbig"><div class="n">🔥 ' +
          (member.currentStreak || 0) +
          '</div><div class="c">day streak</div></div>' +
          '<div class="msgcard"><div class="lbl">All time</div>' +
          (member.daysPlayed || 0) +
          " days played · longest streak " +
          (member.longestStreak || 0) +
          "</div>" +
          (rows
            ? '<div class="otherwrap"><div class="h">How you do by theme</div>' +
              rows +
              "</div>"
            : '<div class="sub">Nothing recorded yet.</div>') +
          '<button class="ghost" id="ed-back">Back to results</button>' +
          "</div>";

        document.getElementById("ed-back").onclick = renderEnd;
      })
      .catch(function (err) {
        renderApiError(err.message || String(err));
      });
  }

  function waitingHtml(label) {
    return (
      '<div class="waiting" role="status"><span class="spin"></span>' +
      esc(label) +
      "</div>"
    );
  }

  function renderLoading() {
    el.innerHTML =
      chrome(state.streak, 0) +
      '<div class="screen"><div class="kick">Loading</div><h1>Fetching today’s questions…</h1>' +
      waitingHtml("This only takes a moment") +
      "</div>";
  }

  function renderApiError(msg) {
    el.innerHTML =
      chrome(state.streak, 0) +
      '<div class="screen"><div class="kick">Couldn’t load</div><h1>Could not load today’s quiz</h1>' +
      '<div class="sub">Check your connection and try again. Nothing you have already answered has been lost.</div>' +
      '<div class="acedLine">' +
      esc(msg) +
      "</div>" +
      '<button class="btn" id="ed-retry">Try again</button></div>';
    document.getElementById("ed-retry").onclick = boot;
  }

  function boot() {
    if (!apiOn()) {
      renderApiError(
        "Missing API base URL. Pass ?apiBase=http://localhost:4001 (or set window.__ESTI_API_BASE_URL__).",
      );
      return;
    }
    if (!me.uid) {
      renderApiError(
        "No member id. Circle normally provides it; locally pass ?uid=someone.",
      );
      return;
    }

    renderLoading();
    fetchToday()
      .then(function (data) {
        applyTodayPayload(data);

        if (!QUEUE.length) {
          renderEmptyDay();
          return;
        }
        if (PROGRESS.completed) {
          renderAlreadyPlayed();
          return;
        }
        if (PROGRESS.answeredCount > 0) {
          renderResume();
          return;
        }
        renderHome();
      })
      .catch(function (err) {
        renderApiError(err.message || String(err));
      });
  }

  // ---------- BOOT ----------
  boot();
})();
